  if(workspace&&!project)return <DocumentLoadBoundary active={documentLoading}><EmptyWorkspace contextKey={JSON.stringify(controller.document)} onApplyLayers={applyS57Layers} onUndo={undo} onRedo={redo} canUndo={!!past.length} canRedo={!!future.length} workspace={workspace} aggregate={controller.aggregate} pending={busy||controller.pending} error={controller.relationError} dirty={dirty} notice={notice} onDismiss={()=>setNotice(null)} onSave={save} onOpen={openProject} onRestore={restore} onImport={importWorkspace} onExport={()=>doExport('project')} onAction={workspaceAction} onActivate={activatePath} onAnalyze={controller.analyze} onRename={renameWorkspace} notify={notify}/></DocumentLoadBoundary>;
  if(!project)return <div className="startup"><Anchor size={50}/><h1>OceanRoute</h1><p>海底电缆规划与敷设工程</p>{status==='error'?<><div className="startup-error">本地计算服务连接失败。请启动 OceanRoute 服务后重试。</div><button className="primary-button" onClick={()=>loadSample()}><RefreshCw size={16}/>重新连接</button></>:<span><LoaderCircle className="spin" size={18}/>正在载入工程数据…</span>}{notice&&<div className="startup-error">{notice.message}</div>}</div>;
